  "helpWorkerOtpTitle": "ओटीपी पडताळणी आणि काम पूर्ण",
  "helpWorkerProfileDesc": "ਆਪਣੀ ਪ੍ਰੋਫਾਈਲ, ਕਿੱਤਾ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਅਤੇ KYC ਦਸਤਾਵੇਜ਼ਾਂ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰੋ।",
  "helpWorkerProfileTitle": "ਪ੍ਰੋਫਾਈਲ ਅਤੇ KYC",
