  "helpWorkerSocialSecurityStep1": "प्रत्येक पूर्ण कामासोबत प्रधानमंत्री सुरक्षा विमा योजना (PMSBY) सक्रिय राहते.",
  "helpWorkerSocialSecurityStep2": "सहकारी महासंघ अटल पेन्शन योजनेमध्ये (APY) ५०% वाढीव योगदान देते.",
  "helpWorkerSocialSecurityStep3": "आपत्कालीन वैद्यकीय मदत किंवा कल्याणकारी लाभांसाठी थेट पोर्टलवरून अर्ज करा.",
  "helpWorkerSocialSecurityTitle": "सामाजिक सुरक्षा आणि कल्याणकारी योजना",
